INSERT OR IGNORE INTO stories (id, title, description, cover, slides, outlink_url, outlink_text, published, created_at, updated_at) VALUES ('trending-instagram-chatgpt-photo-editing-prompts', '5 ChatGPT photo editing prompts trending on Instagram', 'Five looks creators keep reusing: golden hour, 90s flash, collage, collectible figure and hand-painted anime. Swipe, copy, paste into ChatGPT.', '/stories/trending-instagram-chatgpt-photo-editing-prompts-poster.webp', '[{"image":"/stories/trending-instagram-chatgpt-photo-editing-prompts-1.webp","heading":"Trending on Instagram","text":"ChatGPT photo editing prompts that keep going viral. Swipe to copy five of them."},{"image":"/stories/trending-instagram-chatgpt-photo-editing-prompts-2.webp","heading":"Golden hour portrait","text":"Warm backlight, soft rim light, natural skin. Say \"keep my face unchanged\" to protect your look."},{"image":"/stories/trending-instagram-chatgpt-photo-editing-prompts-3.webp","heading":"90s disposable camera","text":"Direct flash, faded color and light grain. Add \"small light leaks\" for the date-stamp feel."},{"image":"/stories/trending-instagram-chatgpt-photo-editing-prompts-4.webp","heading":"Three-frame collage","text":"Ask for three instant-film frames with slightly different crops of the same photo."},{"image":"/stories/trending-instagram-chatgpt-photo-editing-prompts-5.webp","heading":"Collectible figure style","text":"A glossy figure on a round display base. Name the backdrop color to stay on brand."},{"image":"/stories/trending-instagram-chatgpt-photo-editing-prompts-6.webp","heading":"Hand-painted anime frame","text":"Watercolor sky, painterly clouds, soft outlines. Keep your pose and outfit the same."},{"image":"/stories/trending-instagram-chatgpt-photo-editing-prompts-7.webp","heading":"Copy every prompt free","text":"Tap Copy Prompt on promptbin, paste into ChatGPT with your photo and refine one detail."}]', '/blog/trending-instagram-chatgpt-photo-editing-prompts/', 'Read the full guide', 1, '2026-10-12T00:00:00.000Z', '2026-10-12T00:00:00.000Z');
INSERT OR IGNORE INTO stories (id, title, description, cover, slides, outlink_url, outlink_text, published, created_at, updated_at) VALUES ('couple-prompt-chatgpt-scenes', 'Couple prompt ChatGPT: 5 scenes that keep both faces', 'A couple prompt ChatGPT can follow: beach sunset, neon street, festive lights, rainy city and instant film, each with an identity lock.', '/stories/couple-prompt-chatgpt-scenes-poster.webp', '[{"image":"/stories/couple-prompt-chatgpt-scenes-1.webp","heading":"Couple prompts for ChatGPT","text":"Five scenes, one rule: keep both faces, outfits and poses unchanged."},{"image":"/stories/couple-prompt-chatgpt-scenes-2.webp","heading":"Sunset beach","text":"Pink and orange sky, gentle waves, soft light on both faces."},{"image":"/stories/couple-prompt-chatgpt-scenes-3.webp","heading":"Neon street at night","text":"Neon reflections on wet pavement. Describe the light, not the people."},{"image":"/stories/couple-prompt-chatgpt-scenes-4.webp","heading":"Festive lights","text":"Warm string lights and soft bokeh. Keep skin tones the same."},{"image":"/stories/couple-prompt-chatgpt-scenes-5.webp","heading":"Rainy city evening","text":"A shared umbrella, street lights on wet pavement and a calm, romantic mood."},{"image":"/stories/couple-prompt-chatgpt-scenes-6.webp","heading":"Instant-film portrait","text":"White border, faded colors and a short handwritten caption."},{"image":"/stories/couple-prompt-chatgpt-scenes-7.webp","heading":"Find more couple prompts","text":"Open promptbin, pick the Couple filter and copy a prompt in one tap."}]', '/blog/chatgpt-couple-photo-prompts/', 'Read the couple guide', 1, '2026-10-12T00:00:00.000Z', '2026-10-12T00:00:00.000Z');
INSERT OR IGNORE INTO stories (id, title, description, cover, slides, outlink_url, outlink_text, published, created_at, updated_at) VALUES ('chatgpt-photo-editing-prompts-text', 'ChatGPT photo editing prompts text: add words, keep faces', 'How to add headlines, quotes and names to photos with ChatGPT. Exact wording, one lettering style and a clear position.', '/stories/chatgpt-photo-editing-prompts-text-poster.webp', '[{"image":"/stories/chatgpt-photo-editing-prompts-text-1.webp","heading":"Text on photos with ChatGPT","text":"Give the exact words, a lettering style and a position. Keep faces uncovered."},{"image":"/stories/chatgpt-photo-editing-prompts-text-2.webp","heading":"Magazine cover","text":"Bold sans-serif headline at the top, small subtitle at the bottom."},{"image":"/stories/chatgpt-photo-editing-prompts-text-3.webp","heading":"Quote overlay","text":"Elegant handwriting in the lower third, white with a soft shadow."},{"image":"/stories/chatgpt-photo-editing-prompts-text-4.webp","heading":"Birthday card","text":"Rounded playful lettering above the head and small confetti around the edge."},{"image":"/stories/chatgpt-photo-editing-prompts-text-5.webp","heading":"Travel poster","text":"A bold condensed title on a solid color band at the bottom."},{"image":"/stories/chatgpt-photo-editing-prompts-text-6.webp","heading":"Check every letter","text":"Keep phrases short. Long sentences are where spelling mistakes appear."}]', '/blog/chatgpt-photo-editing-prompts-text/', 'Read the text guide', 1, '2026-10-12T00:00:00.000Z', '2026-10-12T00:00:00.000Z');
